function readStore(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value===null?fallback:value}catch{return fallback}}
function makeParty(name,players=[]){return{id:`party-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,name,players:[...players],scores:{},stats:{},history:[]}}
const savedPlayers=readStore('imposter.players',[...DEFAULT_NAMES]);
const savedScores=readStore('imposter.scores',{});
const savedSettings=readStore('imposter.settings',{});
const savedParties=readStore('imposter.parties',[]);
const parties=Array.isArray(savedParties)?savedParties.filter(p=>p&&p.id&&Array.isArray(p.players)).map(p=>({...p,scores:p.scores||{},stats:p.stats||{},history:Array.isArray(p.history)?p.history:[]})):[];
if(!parties.length)parties.push({...makeParty('My Party',savedPlayers),scores:savedScores});
const selectedParty=parties.find(p=>p.id===localStorage.getItem('imposter.activeParty'))||parties[0];
const state = {
  parties,activePartyId:selectedParty.id,players:selectedParty.players,scores:selectedParty.scores,
  settings:{imposters:1,timer:60,guess:true,categories:['Random Mix'],hints:false,typedClues:true,...savedSettings},

  usedWords: [], round: 1, phase: 'setup', roleIndex: 0, clueIndex: 0, voteIndex: 0,
  roles: [], eliminated: [], voteRounds: [], word: '', wordCategory:'', hint:'', matchId:'', startingPlayer:'', verbalStarted:false, clues: [], votes: {}, selectedVote: null, seconds: 0, interval: null,
  result: null, sound: true, revealed: false, roleSeen: false, editing: -1, selectedStatPlayer:null
};
const app = document.querySelector('#app');
const toastEl = document.querySelector('#toast');
function save(){const party=state.parties.find(p=>p.id===state.activePartyId);if(party){party.players=state.players;party.scores=state.scores}localStorage.setItem('imposter.players',JSON.stringify(state.players));localStorage.setItem('imposter.scores',JSON.stringify(state.scores));localStorage.setItem('imposter.settings',JSON.stringify(state.settings));localStorage.setItem('imposter.parties',JSON.stringify(state.parties));localStorage.setItem('imposter.activeParty',state.activePartyId)}
function esc(s){ return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.classList.remove('show'),2100)}
function randomize(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
