function switchParty(id){const current=state.parties.find(p=>p.id===state.activePartyId);if(current){current.players=state.players;current.scores=state.scores}const party=state.parties.find(p=>p.id===id);if(!party)return;state.activePartyId=party.id;state.players=party.players;state.scores=party.scores;save();render()}
function createParty(){app.insertAdjacentHTML('beforeend',`<div class="pack-modal" id="partyModal"><div class="modal-card"><h2>Start a fresh party</h2><p>This party gets its own players, scores, match history, and statistics.</p><label for="partyName">Party name</label><input id="partyName" class="text-input" maxlength="30" placeholder="My Friends"><div class="modal-actions"><button class="secondary-btn" id="cancelParty">Cancel</button><button class="primary-btn" id="saveParty">Create party</button></div></div></div>`);const close=()=>document.querySelector('#partyModal')?.remove();document.querySelector('#cancelParty').onclick=close;document.querySelector('#partyModal').onclick=e=>{if(e.target.id==='partyModal')close()};document.querySelector('#saveParty').onclick=()=>{const name=document.querySelector('#partyName').value.trim();if(!name){toast('Give your party a name first.');return}if(state.parties.some(p=>p.name.toLowerCase()===name.toLowerCase())){toast('A party with that name already exists.');return}const party=makeParty(name);state.parties.push(party);state.activePartyId=party.id;state.players=party.players;state.scores=party.scores;save();close();render();toast('Fresh party created!')}}
function addPlayer(){const input=document.querySelector('#playerInput'),name=input.value.trim();if(!name)return;if(state.players.length>=12){toast('The room is full (12 players max).');return}if(state.players.some(n=>n.toLowerCase()===name.toLowerCase())){toast('That name is already in the room.');input.focus();return}state.players.push(name);save();render();document.querySelector('#playerInput').focus()}
function saveEdit(commit){const input=document.querySelector('.edit-name');if(!input)return;const idx=+input.dataset.index;const name=input.value.trim();if(commit&&name&&!state.players.some((n,i)=>i!==idx&&n.toLowerCase()===name.toLowerCase()))state.players[idx]=name;else if(commit&&name)toast('Choose a name that’s not already taken.');state.editing=-1;save();render()}
function startGame(){const v=document.querySelector('#validation');if(state.players.length<3||state.settings.imposters>=state.players.length||state.settings.imposters<1){if(v)v.textContent=state.players.length<3?'Add at least 3 players to start.':'Leave at least two non-imposters in the game.';return}if(!state.settings.categories.length){if(v)v.textContent='Pick at least one word category.';return}
 const pool=[...new Set(state.settings.categories.flatMap(wordsFor))];if(!pool.length){toast('No words available. Choose another category.');return}let fresh=pool.filter(w=>!state.usedWords.includes(w));if(!fresh.length){state.usedWords=[];fresh=pool}state.word=fresh[Math.floor(Math.random()*fresh.length)];state.usedWords.push(state.word);state.wordCategory=state.settings.categories.find(category=>wordsFor(category).includes(state.word))||BASE_CATEGORIES.find(category=>wordsFor(category).includes(state.word))||'Uncategorized';state.hint=state.settings.hints?generateHint(state.word,state.wordCategory):'';state.matchId=`match-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;state.startingPlayer='';state.verbalStarted=false;const order=randomize([...state.players]);const bad=randomize([...order]).slice(0,state.settings.imposters);state.roles=order.map(name=>({name,imposter:bad.includes(name)}));state.clues=[];state.votes={};state.voteRounds=[];state.eliminated=[];state.selectedVote=null;state.voteIndex=0;state.roleIndex=0;state.revealed=false;state.roleSeen=false;state.phase='deal';render()}
function renderDeal(){const p=state.roles[state.roleIndex];const last=state.roleIndex===state.roles.length-1;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> SECRET ROLE</div><span class="round-tag">${state.roleIndex+1} OF ${state.players.length}</span></div><section class="panel phase-card"><div class="step-count">PRIVATE SCREEN · ONLY ${esc(p.name.toUpperCase())} SHOULD LOOK</div><h1>Pass the phone<br>to <em>${esc(p.name)}.</em></h1><p class="phase-description">Make sure everyone else is looking away. Tap below when you’re ready to see your role.</p><div class="secret-box ${state.revealed?'':'hidden'}">${state.revealed?`${p.imposter?`<div class="secret-value">YOU ARE THE IMPOSTER</div><div class="secret-role danger">${state.settings.hints?`HINT: ${esc(state.hint)}`:'BLEND IN. YOU DO NOT KNOW THE WORD.'}</div>`:`<div class="secret-value">${esc(state.word.toUpperCase())}</div><div class="category-label">CATEGORY</div><div class="category-value">${esc(state.wordCategory||'Uncategorized').toUpperCase()}</div><div class="secret-role">YOU ARE IN THE KNOW · KEEP IT SECRET</div>`}`:`<div class="secret-value" style="color:#a7aaa0">••••••••</div><div class="secret-role">YOUR ROLE IS HIDDEN</div>`}</div><p class="hold-note">${state.revealed?'Memorize it. Then tap hide before passing the phone.':'No peeking, everyone else 👀'}</p><div class="action-row">${state.revealed?`<button id="hideRole" class="secondary-btn">Hide my role</button><button id="nextRole" class="primary-btn">${last?'EVERYONE’S READY':'PASS TO NEXT PLAYER'} &nbsp;→</button>`:`<button id="revealRole" class="primary-btn">REVEAL MY ROLE &nbsp;👁</button>${state.roleSeen?`<button id="nextRole" class="secondary-btn">${last?'EVERYONE’S READY':'PASS TO NEXT PLAYER'} &nbsp;→</button>`:''}`}</div><div class="progress-dots">${state.roles.map((_,i)=>`<span class="${i<=state.roleIndex?'done':''}"></span>`).join('')}</div></section><div class="setup-footnote">KEEP YOUR SCREEN TO YOURSELF — THE WHOLE GAME DEPENDS ON IT</div></div>`;
 const revealButton=document.querySelector('#revealRole');if(revealButton)revealButton.onclick=()=>{state.revealed=true;state.roleSeen=true;render()};if(state.revealed)document.querySelector('#hideRole').onclick=()=>{state.revealed=false;render()};if(state.revealed||state.roleSeen)document.querySelector('#nextRole').onclick=()=>{state.revealed=false;state.roleSeen=false;if(last){if(state.settings.typedClues){state.phase='clues';state.clueIndex=0}else{state.startingPlayer=getStartingPlayer();state.verbalStarted=false;state.phase='startingPlayer'}}else state.roleIndex++;render()}
}
function activePlayers(){return state.players.filter(name=>!state.eliminated.includes(name))}
 function activeRoles(){const active=new Set(activePlayers());return state.roles.filter(p=>active.has(p.name))}
 function getStartingPlayer(){const roles=activeRoles();const saved=readStore('imposter.startingPlayer',null);if(saved&&saved.matchId===state.matchId&&saved.partyId===state.activePartyId&&roles.some(p=>p.name===saved.name))return saved.name;const available=saved&&saved.partyId===state.activePartyId?roles.filter(p=>p.name!==saved.name):roles;const pool=available.length?available:roles;const player=pool[Math.floor(Math.random()*pool.length)].name;localStorage.setItem('imposter.startingPlayer',JSON.stringify({matchId:state.matchId,partyId:state.activePartyId,name:player}));return player}
 function renderStartingPlayer(){app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} · GAME START</div><span class="round-tag">VERBAL CLUES</span></div><section class="panel phase-card starting-player-card"><div class="eyebrow">WHO'S STARTING?</div><h1 class="starting-player-name">${esc(state.startingPlayer)}</h1><p class="phase-description">You’re the first to give a clue!</p><div class="verbal-instruction">Start the discussion by saying your clue out loud. <strong>No typing required.</strong></div><p class="verbal-status">The group can discuss the secret word and give clues verbally.</p><div class="action-row start-discussion-row"><button id="startVerbalGame" class="primary-btn">START VERBAL DISCUSSION &nbsp;→</button></div></section><div class="setup-footnote">KEEP THE WORD SECRET · EVERYONE GETS ONE VOTE</div></div>`;document.querySelector('#startVerbalGame').onclick=()=>{state.verbalStarted=true;state.phase='verbalDiscussion';if(state.settings.timer)state.seconds=state.settings.timer;render();if(state.settings.timer)startTimer()}}
 function renderVerbalDiscussion(){app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} · DISCUSSION</div><span class="round-tag">${state.settings.timer?'DISCUSSION TIMER':'GET TALKING'}</span></div><section class="panel phase-card starting-player-card"><div class="eyebrow">DISCUSSION HAS BEGUN</div><h1 class="starting-player-name">${esc(state.startingPlayer)} <em>starts.</em></h1><p class="phase-description">Give clues out loud, compare ideas, and decide who might be bluffing. No typing required.</p>${state.settings.timer?`<div class="timer" id="timerValue">${clock(state.seconds)}</div>`:''}<div class="action-row"><button id="continueToVote" class="primary-btn">CONTINUE TO VOTING &nbsp;→</button></div></section><div class="setup-footnote">EVERYONE HAS ONE VOTE · YOU CAN’T VOTE FOR YOURSELF</div></div>`;document.querySelector('#continueToVote').onclick=()=>{clearInterval(state.interval);state.phase='vote';render()}}
 function renderClues(){const roles=activeRoles(),p=roles[state.clueIndex];const done=state.clueIndex>=roles.length;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> CLUE ROUND</div><span class="round-tag">${Math.min(state.clueIndex+1,roles.length)} OF ${roles.length}</span></div><section class="panel clue-card"><div class="clue-top"><h2 class="settings-title">One clue. Keep it clever.</h2><span class="pill-info">NO SAYING THE WORD</span></div>${done?`<div class="center"><p class="phase-description">All clues are in. Talk it out, then cast your votes.</p><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div><button id="beginDiscussion" class="primary-btn" style="max-width:320px">${state.settings.timer?'START DISCUSSION TIMER':'GO TO VOTING'} &nbsp;→</button></div>`:`<div class="current-turn"><span class="avatar">${esc(p.name.charAt(0).toUpperCase())}</span><div><strong>${esc(p.name)}’s turn</strong><small>Pass the phone privately</small></div></div><div class="clue-entry"><input id="clueInput" class="text-input" maxlength="35" autocomplete="off" placeholder="Type a one-word clue…"><button id="submitClue" class="add-btn">Give clue →</button></div><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div>`}</section><div class="setup-footnote">HINTS, NOT DEFINITIONS. GIVE THEM SOMETHING TO DISCUSS.</div></div>`;
 if(done){document.querySelector('#beginDiscussion').onclick=()=>{if(state.settings.timer){state.phase='discussion';state.seconds=state.settings.timer;render();startTimer()}else{state.phase='vote';render()}}}else{const input=document.querySelector('#clueInput');document.querySelector('#submitClue').onclick=submitClue;input.onkeydown=e=>{if(e.key==='Enter')submitClue()};input.focus()}}
function submitClue(){const input=document.querySelector('#clueInput'),clue=input.value.trim();if(!clue){toast('Add a clue before passing the phone.');return}if(clue.toLowerCase().includes(state.word.toLowerCase())){toast('Oops — don’t give the word away!');return}state.clues.push({name:activeRoles()[state.clueIndex].name,clue});state.clueIndex++;render()}
function startTimer(){clearInterval(state.interval);state.interval=setInterval(()=>{state.seconds--;if(state.seconds<=0){clearInterval(state.interval);state.seconds=0;state.phase='vote';render();toast('Time’s up! Time to vote.');return}const el=document.querySelector('#timerValue');if(el){el.textContent=clock(state.seconds);if(state.seconds<=10)el.classList.add('urgent')}},1000)}
function clock(s){return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
function renderDiscussion(){app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> DISCUSSION</div><span class="round-tag">GET TALKING</span></div><section class="panel phase-card discussion-card"><div class="eyebrow">TIME LEFT</div><div class="timer" id="timerValue">${clock(state.seconds)}</div><p class="phase-description">Compare the clues. Who sounds like they’re bluffing? Make your case, but don’t give the word away.</p><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div><div class="action-row"><button id="endDiscussion" class="primary-btn" style="max-width:300px">WE’RE READY TO VOTE &nbsp;→</button></div></section><div class="setup-footnote">EVERYONE HAS ONE VOTE. YOU CAN’T VOTE FOR YOURSELF.</div></div>`;document.querySelector('#endDiscussion').onclick=()=>{clearInterval(state.interval);state.phase='vote';render()}}
function renderVote(){const voters=activePlayers(),targets=activePlayers(),voter=voters[state.voteIndex];const final=state.voteIndex===voters.length-1;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> PRIVATE VOTE</div><span class="round-tag">VOTE ${state.voteIndex+1} OF ${voters.length}</span></div><section class="panel phase-card"><div class="step-count">SECRET BALLOT · ONLY ${esc(voter.name.toUpperCase())} SHOULD LOOK</div><h1>${esc(voter.name)},<br>who’s the imposter?</h1><p class="phase-description">Choose one person you think is bluffing, or skip your vote.</p><div class="vote-select">${targets.map((name,i)=>`<button class="vote-option ${state.selectedVote===String(i)?'selected':''}" data-vote="${i}" ${name===voter.name?'disabled':''}><span class="avatar">${esc(name.charAt(0).toUpperCase())}</span><strong>${esc(name)}</strong></button>`).join('')}<button class="vote-option ${state.selectedVote==='skip'?'selected':''}" data-vote="skip"><span class="avatar">—</span><strong>Skip Vote</strong></button></div><div class="action-row"><button id="castVote" class="primary-btn" style="max-width:320px" ${state.selectedVote===null?'disabled':''}>${final?'LOCK IN & REVEAL VOTES':'SUBMIT SECRET VOTE'} &nbsp;→</button></div></section><div class="setup-footnote">YOUR VOTE IS PRIVATE UNTIL EVERYONE HAS VOTED.</div></div>`;
 document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{state.selectedVote=b.dataset.vote;render()});document.querySelector('#castVote').onclick=()=>{if(state.selectedVote===null)return;state.votes[voter.name]=state.selectedVote==='skip'?'Skip Vote':targets[Number(state.selectedVote)];state.selectedVote=null;if(final)resolveVotes();else{state.voteIndex++;render()}}}
function resolveVotes(){if(state.phase!=='vote')return;const players=activePlayers(),choices=[...players,'Skip Vote'],counts=Object.fromEntries([...state.players.map(name=>[name,0]),['Skip Vote',0]]);Object.values(state.votes).forEach(name=>{if(Object.hasOwn(counts,name))counts[name]++});const max=Math.max(...choices.map(name=>counts[name]));const leaders=choices.filter(name=>counts[name]===max);const eliminated=leaders.length===1&&leaders[0]!=='Skip Vote'?leaders[0]:null;if(eliminated&&!state.eliminated.includes(eliminated))state.eliminated.push(eliminated);const imposters=state.roles.filter(p=>p.imposter).map(p=>p.name),caught=state.eliminated.filter(name=>imposters.includes(name)),remainingImposters=players.filter(name=>!state.eliminated.includes(name)&&imposters.includes(name)).length,remainingPlayers=players.filter(name=>!state.eliminated.includes(name)&&!imposters.includes(name)).length;const winner=remainingImposters===0?'players':remainingImposters>=remainingPlayers?'imposters':null;state.result={round:state.round,counts,max,leaders,imposters,caught,eliminated,activePlayers:[...players],votes:{...state.votes},winner,reason:winner==='players'?'caught':'escaped'};state.voteRounds.push({round:state.round,counts:{...counts},leaders:[...leaders],eliminated,votes:{...state.votes}});if(winner==='players'&&state.settings.guess){state.phase='guess';renderGuess()}else if(winner)finishGame(winner);else{state.phase='roundResult';render()}}
function renderRoundResult(){const r=state.result;const voteHtml=r.activePlayers.map(name=>`<div class="result-player"><span>${esc(name)}${r.leaders.includes(name)?' <b>· TOP VOTE</b>':''}</span><strong>${r.counts[name]} vote${r.counts[name]===1?'':'s'}</strong></div>`).join('');const eliminated=r.eliminated?`<p class="phase-description"><strong>${esc(r.eliminated)}</strong> was eliminated.</p>`:'<p class="phase-description">Skip Vote or a tie won this round. Nobody was eliminated.</p>';app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} · THE REVEAL</div><span class="round-tag">ROUND OVER</span></div><section class="panel phase-card"><div class="step-count">VOTING RESULTS</div><h1>${r.eliminated?`${esc(r.eliminated)} is out.`:'No elimination.'}</h1>${eliminated}<div class="result-banner"><strong>Imposters still active: ${activePlayers().filter(name=>r.imposters.includes(name)).length}</strong></div><div class="result-grid">${voteHtml}<div class="result-player"><span>Skip Vote</span><strong>${r.counts['Skip Vote']} vote${r.counts['Skip Vote']===1?'':'s'}</strong></div></div><div class="action-row" style="margin-top:22px"><button id="continueRound" class="primary-btn" style="max-width:320px">CONTINUE TO ROUND ${state.round+1} &nbsp;→</button></div></section></div>`;document.querySelector('#continueRound').onclick=()=>{state.round++;state.votes={};state.voteIndex=0;state.selectedVote=null;state.clues=[];state.clueIndex=0;state.startingPlayer='';state.verbalStarted=false;state.phase=state.settings.typedClues?'clues':'startingPlayer';if(!state.settings.typedClues)state.startingPlayer=getStartingPlayer();render()}}
function renderGuess(){const imposters=state.result.caught;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ONE LAST CHANCE</div><span class="round-tag">IMPOSTER GUESS</span></div><section class="panel phase-card"><div class="step-count">${imposters.map(n=>esc(n.toUpperCase())).join(' & ')}</div><h1>You’ve been found.<br><em>But do you know?</em></h1><p class="phase-description">The room got you. Guess the secret word correctly and steal the win for the imposter team.</p><form id="guessForm" class="clue-entry" style="max-width:400px;margin:0 auto"><input id="guessInput" class="text-input" maxlength="50" autocomplete="off" placeholder="Your final guess…"><button class="add-btn" type="submit">GUESS</button></form></section><div class="setup-footnote">ONE GUESS FOR THE IMPOSTER TEAM. TALK IT OVER.</div></div>`;document.querySelector('#guessForm').onsubmit=e=>{e.preventDefault();const guess=document.querySelector('#guessInput').value.trim();if(!guess){toast('Enter your guess first.');return}finishGame(guess.toLowerCase()===state.word.toLowerCase()?'imposters':'players',guess)}}
function finishGame(winner,guess=''){clearInterval(state.interval);if(!state.matchId||state.completedMatchId===state.matchId)return;state.completedMatchId=state.matchId;const party=state.parties.find(p=>p.id===state.activePartyId);if(!party)return;const imposters=[...state.result.imposters];state.players.forEach(name=>{const isImposter=imposters.includes(name),won=(winner==='imposters')===isImposter,reward=won?(isImposter?2:1):0;state.scores[name]=(state.scores[name]||0)+reward;const stat=party.stats[name]||{played:0,wins:0,playerWins:0,imposterRounds:0,imposterWins:0,points:0};stat.played++;if(isImposter)stat.imposterRounds++;if(won){stat.wins++;if(isImposter)stat.imposterWins++;else stat.playerWins++}stat.points+=reward;party.stats[name]=stat});state.result.winner=winner;state.result.guess=guess;party.history.unshift({id:state.matchId,date:new Date().toISOString(),word:state.word,winner,players:[...state.players],imposters,guess,clues:state.clues.map(c=>({...c})),votes:{...state.votes}});state.phase='result';save();render()}
function renderResult(){const r=state.result,playerWin=r.winner==='players';const reason=r.reason==='caught'?(playerWin?'The room found every imposter.':''):'The imposter team slipped through.';const voteHtml=state.players.map(n=>`<div class="result-player"><span>${esc(n)}${r.leaders.includes(n)?' <b>· TOP VOTE</b>':''}</span><strong>${r.counts[n]} vote${r.counts[n]===1?'':'s'}</strong></div>`).join('')+`<div class="result-player"><span>Skip Vote${r.leaders.includes('Skip Vote')?' <b>· TOP VOTE</b>':''}</span><strong>${r.counts['Skip Vote']||0} vote${r.counts['Skip Vote']===1?'':'s'}</strong></div>`;const scoreNames=[...state.players].sort((a,b)=>(state.scores[b]||0)-(state.scores[a]||0));app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> THE REVEAL</div><span class="round-tag">GAME OVER</span></div><section class="panel phase-card"><div class="step-count">${playerWin?'THE ROOM WAS RIGHT':'THE IMPOSTER TAKES IT'}</div><h1>${playerWin?'Imposter caught.':'Nice bluff.'}<br><em>${playerWin?'Good eye, everyone.':'You had us.'}</em></h1><p class="phase-description">${esc(reason)}${r.guess?` Their final guess: “${esc(r.guess)}.”`:''}</p><div class="result-banner ${playerWin?'':'bad'}"><strong>The secret word was ${esc(state.word)}.</strong><br>Imposter${r.imposters.length>1?'s':''}: ${r.imposters.map(esc).join(', ')}${r.leaders.length>1?` · Tied top votes: ${r.leaders.map(esc).join(', ')}`:''}</div><div class="result-grid">${voteHtml}</div><div class="scoreboard"><h3>ROOM SCOREBOARD</h3>${scoreNames.map(n=>`<div class="score-row"><span>${esc(n)}${r.imposters.includes(n)?' <span class="role-tag imposter">IMPOSTER</span>':''}</span><strong>${state.scores[n]||0} pts</strong></div>`).join('')}</div><div class="action-row" style="margin-top:22px"><button id="nextRound" class="primary-btn" style="max-width:280px">PLAY ANOTHER ROUND &nbsp;↻</button><button id="backSetup" class="secondary-btn">BACK TO SETUP</button></div><div class="setup-footnote">NORMAL PLAYER WIN: +1 EACH · IMPOSTER WIN: +2 EACH</div></section></div>`;document.querySelector('#nextRound').onclick=()=>{state.round++;state.phase='setup';startGame()};document.querySelector('#backSetup').onclick=()=>{state.phase='setup';state.round=1;state.usedWords=[];render()}}
function renderStats(){const party=state.parties.find(p=>p.id===state.activePartyId);if(!party){state.phase='setup';renderSetup();return}const names=[...new Set([...party.players,...Object.keys(party.stats)])].sort((a,b)=>(party.stats[b]?.points||party.scores[b]||0)-(party.stats[a]?.points||party.scores[a]||0));const selected=state.selectedStatPlayer,stat=selected?party.stats[selected]||{played:0,wins:0,playerWins:0,imposterRounds:0,imposterWins:0,points:party.scores[selected]||0}:null;const history=party.history||[];app.innerHTML=`<div class="phase-wrap stats-wrap"><div class="phase-head"><div><div class="eyebrow">PARTY RECORD</div><h1>${esc(party.name)} <em>stats.</em></h1></div><span class="round-tag">${history.length} MATCH${history.length===1?'':'ES'}</span></div><section class="panel stats-panel"><div class="stats-toolbar"><div><h2 class="settings-title">${selected?`${esc(selected)}’s stats`:'Party leaderboard'}</h2><p class="phase-description">Completed matches only · stored on this device</p></div><button id="backStats" class="secondary-btn">BACK TO SETUP</button></div>${selected?`<div class="stats-metrics"><div><strong>${stat.played}</strong><span>GAMES PLAYED</span></div><div><strong>${stat.wins}</strong><span>TEAM WINS</span></div><div><strong>${stat.playerWins}</strong><span>ROOM WINS</span></div><div><strong>${stat.imposterRounds}</strong><span>IMPOSTER ROUNDS</span></div><div><strong>${stat.imposterWins}</strong><span>IMPOSTER WINS</span></div><div><strong>${stat.points}</strong><span>POINTS</span></div></div><button class="mini-link" id="clearPlayer">← ALL PLAYERS</button>`:`<div class="party-summary"><div><strong>${history.length}</strong><span>COMPLETED MATCHES</span></div><div><strong>${history.filter(m=>m.winner==='players').length}</strong><span>ROOM WINS</span></div><div><strong>${history.filter(m=>m.winner==='imposters').length}</strong><span>IMPOSTER WINS</span></div></div><div class="stats-list">${names.length?names.map((name,i)=>{const s=party.stats[name]||{played:0,wins:0,points:party.scores[name]||0};return`<button class="stats-row" data-stat-player="${esc(name)}"><span class="stats-rank">${i+1}</span><strong>${esc(name)}</strong><span>${s.played} games · ${s.wins} wins</span><b>${s.points} pts</b></button>`}).join(''):'<p class="empty-note">Play a completed match to start your party record.</p>'}</div>`}<div class="history-heading"><h3>MATCH HISTORY</h3><span>${history.length} COMPLETED</span></div><div class="history-list">${history.length?history.slice(0,30).map(m=>`<div class="history-row"><div><strong>${esc(m.word||'—')}</strong><small>${new Date(m.date).toLocaleDateString()} · ${m.players.length} players</small></div><span class="history-winner ${m.winner==='imposters'?'imposter':''}">${m.winner==='imposters'?'IMPOSTER WIN':'ROOM WIN'}</span><small>${m.imposters.map(esc).join(', ')}</small></div>`).join(''):'<p class="empty-note">No completed matches yet.</p>'}</div><div class="stats-footer"><button id="resetStats" class="text-btn danger-text">Reset party stats & history</button></div></section></div>`;document.querySelector('#backStats').onclick=()=>{state.phase='setup';state.selectedStatPlayer=null;render()};document.querySelectorAll('[data-stat-player]').forEach(b=>b.onclick=()=>{state.selectedStatPlayer=b.dataset.statPlayer;render()});document.querySelector('#clearPlayer')?.addEventListener('click',()=>{state.selectedStatPlayer=null;render()});document.querySelector('#resetStats').onclick=()=>{if(!window.confirm(`Reset all scores, stats, and match history for “${party.name}”? This cannot be undone.`))return;party.scores={};party.stats={};party.history=[];state.scores=party.scores;state.selectedStatPlayer=null;save();render();toast('Party stats and history reset.')}}
 document.querySelector('#soundToggle').onclick=()=>{state.sound=!state.sound;document.querySelector('#soundToggle').classList.toggle('muted',!state.sound);document.querySelector('#soundToggle').textContent=state.sound?'♫':'♪'};
render();
